-- Post-check: every calculator exists once, with all its fields, linked to every operation it computes.
DO $post$
DECLARE bad TEXT;
BEGIN
  SELECT string_agg(e.name, ', ') INTO bad
  FROM (VALUES
    ($q$Sand Casting - Risers$q$, 16, 0),
    ($q$Sand Casting - Gating system$q$, 37, 0),
    ($q$Sand Casting - Metal per casting$q$, 6, 0),
    ($q$Sand Casting - Material cost$q$, 9, 0),
    ($q$Sand Casting - Melting$q$, 14, 1),
    ($q$Sand Casting - Moulding (automatic line)$q$, 8, 2),
    ($q$Sand Casting - Moulding (manual flask)$q$, 14, 3),
    ($q$Sand Casting - Pour$q$, 9, 1),
    ($q$Sand Casting - Cooling$q$, 17, 1),
    ($q$Sand Casting - Shakeout$q$, 3, 1),
    ($q$Sand Casting - Shakeout (manual)$q$, 2, 0),
    ($q$Sand Casting - Degating$q$, 5, 1),
    ($q$Sand Casting - Cleaning (shot blast loads)$q$, 3, 1),
    ($q$Sand Casting - Cleaning (blast room)$q$, 3, 0),
    ($q$Sand Casting - Finishing (grinding)$q$, 13, 1),
    ($q$Sand Casting - Visual inspection$q$, 8, 1),
    ($q$Sand Casting - Core sand$q$, 5, 0),
    ($q$Sand Casting - Coremaking$q$, 3, 6),
    ($q$Sand Casting - Hot box coremaking$q$, 21, 1),
    ($q$Sand Casting - Core box$q$, 8, 0)
  ) AS e(name, field_count, mapping_count)
  LEFT JOIN public.calculators c ON c.name = e.name AND c.user_id IS NULL AND c.retired_at IS NULL
  WHERE c.id IS NULL
     OR (SELECT count(*) FROM public.calculator_fields f WHERE f.calculator_id = c.id) <> e.field_count
     OR (SELECT count(*) FROM public.process_calculator_mappings m WHERE m.calculator_id = c.id AND m.process_group = $q$Sand Casting$q$) <> e.mapping_count;
  IF bad IS NOT NULL THEN
    RAISE EXCEPTION 'migration 956: calculators incomplete: %', bad;
  END IF;
END
$post$;

COMMIT;
